#!/usr/bin/env bash
# step198 — About page v2: fill the full site width (hero 2-col + brand panel,
# two-column magazine story, 4-across value cards) instead of a narrow centered
# column. Only views/about.ejs changes (inline styles; no app.css, no cache-buster).
set -uo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
cd "$GSZ" || { echo "FATAL: no $GSZ"; exit 1; }

F=views/about.ejs
cp -p "$F" "$F.bak-step198-$TS"
echo "backup: $F.bak-step198-$TS"
restore(){ echo "!! restoring"; [ -f "$F.bak-step198-$TS" ] && cp -p "$F.bak-step198-$TS" "$F"; }
trap 'restore' ERR

# write the new about.ejs
base64 -d > "$F" <<'B64EOF'

B64EOF

# validate it compiles against the real partials
node -e "const ejs=require('$GSZ/node_modules/ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$GSZ/views/about.ejs','utf8'),{filename:'$GSZ/views/about.ejs'});console.log('ejs ok: about.ejs');" || { echo 'EJS COMPILE FAILED'; restore; exit 2; }
grep -q 'class="ab-hero"' "$F" || { echo 'VERIFY FAILED: ab-hero not present'; restore; exit 3; }
echo "verify ok: about v2 written"

trap - ERR
pm2 restart gsz --update-env >/dev/null 2>&1 || pm2 restart gsz >/dev/null 2>&1
ok=0
for i in $(seq 1 25); do
  code=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/about || true)
  if [ "$code" = "200" ]; then ok=1; echo "about page ok (HTTP 200) after ${i} tries"; break; fi
  sleep 0.6
done
[ "$ok" = "1" ] || { echo "HEALTH CHECK FAILED (last: ${code:-none}) — restoring"; restore; pm2 restart gsz >/dev/null 2>&1; exit 4; }
echo "STEP198 DONE — About page now fills the full width."
